-- Independent explicit branch and offline-life purposes; no existing grant is widened.
ALTER TABLE policy_versions DROP CONSTRAINT policy_versions_kind_check;
ALTER TABLE policy_versions ADD CONSTRAINT policy_versions_kind_check CHECK(kind IN ('privacy_notice','private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions','person_story_branches','person_offline_life'));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_purpose_check;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_purpose_check CHECK(purpose IN ('privacy_notice','private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions','person_story_branches','person_offline_life'));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_check;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_check CHECK((purpose='privacy_notice' AND decision='acknowledge') OR (purpose IN ('private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions','person_story_branches','person_offline_life') AND decision IN ('grant','revoke')));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_ai_notice_binding;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_ai_notice_binding CHECK(CASE
 WHEN purpose IN ('ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions','person_story_branches','person_offline_life') AND decision='grant' THEN notice_authorization_version IS NOT NULL AND notice_authorization_version>0
 WHEN purpose='private_story_storage' AND decision='grant' THEN notice_authorization_version IS NULL OR notice_authorization_version>0
 ELSE notice_authorization_version IS NULL END);

INSERT INTO policy_versions(id,kind,version,document_zh_cn,document_en) VALUES
('1f3fd700-9efe-4090-a78d-e769a7e46133','person_story_branches',1,
'西界故事分支授权（OpenAI 本机验证）
这是独立用途，须另有私人文字保存和 AI 文字处理授权；本决定绑定当前隐私告知，不自动开启其他用途。只有你主动从同一人物主线当前末端创建分支，才会捕获该处有效的共同历史、必要人物资料和当前虚拟场景。分支场景冻结，不跟随主线迁居；分支生成只可使用该人物获准的共同分叉前历史和本分支有效来源，不读取其他人物或分叉后的主线私有历史，不合并回主线。
你在分支内主动提交的文字及必要来源可交给 OpenAI API 生成真实虚拟叙事，采用 store:false 并保留必要模型与来源记录。不存在后台自动分叉或用模板冒充成功；分支不会迁居、赠礼、消费、发放资产、代发用户消息、公开发布或改写真实人物资料。本授权不启用离线生活，也不扩大明确世界行动授权。
处理前后和提交前复核账号、人物、分支、来源和捕获的精确授权版本；来源失效不得继续用于模型。撤回停止新生成、旧任务重试和迟到写入，不能收回已经传给 OpenAI 的内容。重授不复活旧任务。已有历史按私人文字保存权限读取，独立导出和注销不要求重新授权。此版本用于非生产本机合成验证，不代表对外发布。',
'Xijie story branch permission (OpenAI local verification)
This independent purpose also requires private text storage and AI text processing. It binds to the exact current privacy notice and grants no other purpose. Only your explicit fork from the current main endpoint captures that character valid common history, necessary character text and current virtual scene. The branch scene remains frozen across later main-world moves. Generation uses only authorized pre-fork common history and valid sources inside this branch, excluding other characters and post-fork main history. Branches never merge into main.
New text you actively submit within the branch and necessary sources may be sent to the OpenAI API for actual virtual narrative generation with store:false and necessary provenance. No automatic forks or template successes are created. Branches do not relocate, gift, spend, grant assets, impersonate user messages, publish or rewrite real profile facts. This permission neither enables offline life nor expands world-action permission.
Account, character, branch, sources and exact captured grants are checked before and after generation and before commit. Invalid sources cannot continue into models. Withdrawal stops new generation, old retries and late commits but cannot recall content already sent to OpenAI. Regrant never revives old jobs. Existing history remains readable under private text storage; independent export and erasure require no renewed grant. This version supports synthetic non-production local verification, not public release.'),
('8f0d356a-6a7b-450f-91d2-536f4d417918','person_offline_life',1,
'西界人物离线生活授权（OpenAI 本机验证）
这是独立 AI 用途，须同时允许私人文字保存、AI 文字处理、明确虚拟行动与事件记忆和本授权；它绑定当前隐私告知，旧授权不会自动开启本用途。每个人物的离线生活默认关闭，只有你另行明确开启才持续到你暂停；仅在主线当前虚拟场景每天最多形成一次有限、纯叙事的正式虚拟经历。
生成可将该人物必要资料、获准主线历史与有效虚拟事件摘要交给 OpenAI API，采用 store:false 并保存真实模型、来源和任务记录。模型草稿不是已发生事件；只有权限、当前场景和来源全部复核通过，才保存正式事件与记忆摘要。不会消费、赠礼、发放资产、替你发消息、公开发布、迁居、执行真实世界行动、替其他人物行动或进入分支；不声称真实意识、物件或资产改变。不用模板或虚构结果填补模型失败。
暂停停止后续排期，撤回本授权或必要授权停止新处理、旧任务重试及迟到提交。任务前后和提交前校验捕获的精确权限版本、账号、人物、当前场景和来源；重授不会复活旧任务，来源失效不再进入后续 AI。撤回不能收回已发给 OpenAI 的内容。已有历史按私人文字保存权限读取，独立导出与注销不需重新允许。此版本仅用于非生产本机合成验证，不代表对外发布。',
'Xijie character offline life permission (OpenAI local verification)
This independent AI purpose requires private text storage, AI text processing, explicit virtual actions and event memory, and this grant together. It binds to the current privacy notice; earlier grants never enable it. Offline life defaults off per character and requires a separate explicit enable action that continues until paused. It may produce at most one bounded narrative-only committed virtual experience per day on main in the current virtual scene.
Necessary character text, authorized main history and valid virtual event summaries may be sent to the OpenAI API with store:false and actual model, source and job provenance. Drafts are not events. Only after permission, scene and source checks may a formal event and memory summary commit. This scope excludes spending, gifts, asset grants, messages impersonating you, publication, relocation, real-world actions, acting for other characters and branches. It does not claim real consciousness or physical or asset changes. Model failures are never filled with templates or fabricated successes.
Pause stops future scheduling. Withdrawal of this or any required permission stops new processing, old retries and late commits. Exact captured grants, account, character, current scene and sources are checked before and after generation and before commit. Regrant never revives old jobs; invalid sources cannot enter later AI. Withdrawal cannot recall content already sent to OpenAI. Saved history follows private text storage; independent export and erasure require no renewed grant. This version is limited to synthetic non-production local verification, not public release.');
